+  const fieldset = form.querySelector(".radio-group");
+  const errorEl = document.getElementById("notify-error");
+  const statusEl = document.getElementById("form-status");
+  const radios = form.querySelectorAll('input[name="notify"]');
+
+  function clearError() {
+    errorEl.hidden = true;
+    fieldset.removeAttribute("data-invalid");
+    radios.forEach((r) => r.removeAttribute("aria-invalid"));
+  }
+
+  function showError() {
+    errorEl.hidden = false;
+    fieldset.setAttribute("data-invalid", "true");
+    radios.forEach((r) => r.setAttribute("aria-invalid", "true"));
+    const first = radios[0];
+    if (first) first.focus();
+  }
+
+  radios.forEach((radio) => {
+    radio.addEventListener("change", () => {
+      if (radio.checked) clearError();
+    });
+  });
+
+  form.addEventListener("submit", (event) => {
+    event.preventDefault();
+    statusEl.removeAttribute("data-state");
+    statusEl.textContent = "";
+
+    const selected = form.querySelector('input[name="notify"]:checked');
+    if (!selected) {
+      showError();
+      return;
+    }
+
+    clearError();
+    const labels = { email: "Email", sms: "SMS", push: "Push notifications" };
+    statusEl.setAttribute("data-state", "success");
+    statusEl.textContent =
+      "Saved. We'll notify you via " + labels[selected.value] + ".";
+  });
+})();
